'use strict';
const BASE = '8a2dc204c265c07ce8506a3599a28e720b6dcdd7';
const HEAD = '76d21d26c682e1ca6ca25bd8e81edf9f609ac52f';
const escapeHtml = (value) => String(value).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const $ = (id) => document.getElementById(id);
let role = 'developer', page = 'overview', tab = 'impact', entity = 'update';
let nextId = 2, toastTimer;
const reports = [{id:1, title:'缺失文档 ID 的更新与删除行为', type:'history', purpose:'核对跳过不存在的文档 ID 后，更新、删除与 upsert 行为是否保持一致。', base:BASE, head:HEAD, original:'', origin:'', model:true, scenario:'normal', reviews:[]}];
let current = reports[0];
const draft = {type:'history', purpose:'核对跳过不存在的文档 ID 后，更新、删除与 upsert 行为是否保持一致。', base:BASE, head:HEAD, original:'', origin:'', model:true};
const tag = (s, variant='') => `<span class="tag ${variant}">${escapeHtml(s)}</span>`;
const button = (label, action, variant='') => `<button class="button ${variant}" data-action="${action}">${label}</button>`;
function toast(message){$('toast').textContent=message;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),3500);}
function status(r){return ['model-failed','partial'].includes(r.scenario)?'部分完成':'完成';}
function reviewStatus(r){return r.reviews.at(-1)?.decision || '待审核';}
function heading(kicker,title,description,action=''){return `<div class="breadcrumb">工作区 / TinyDB / ${escapeHtml(title)}</div><header class="page-head"><div><div class="eyebrow">${kicker}</div><h1>${escapeHtml(title)}</h1><p class="subtext">${escapeHtml(description)}</p></div>${action}</header>`;}
const footer = `<footer class="provenance">原型内容参考 TinyDB 历史案例 B。方法及版本来自样例核对；布局、解释和交互为设计示例。未执行分析、模型调用或仓库测试。</footer>`;
function overview(){return heading('PROJECT OVERVIEW','先理解项目，再检查修改','从模块职责找到入口，再沿着一次变更查看可能的影响。',role==='developer'?button('＋ 新建分析','new'):'')+`
<section class="hero"><div><div class="eyebrow">TINYDB / PYTHON</div><h2>一个轻量文档数据库，<br>从 Table 看懂数据操作。</h2><p>首版把文件、模块和函数关系连起来，让每条说明都能回到对应版本。这里先从已核对的更新与删除修复开始。</p><div class="meta-row">${tag('744 个可达提交 · 已核对快照')}${tag('概览示例版本 76d21d26')}</div>${button('打开示例报告 ↗','report','secondary small')}</div><div class="hero-diagram" aria-label="模块阅读顺序示意，不代表已解析调用链"><span>数据库入口</span><b>›</b><span>Table</span><b>›</b><span>Storage</span><small class="muted">模块阅读顺序示意</small></div></section>
<div class="grid-two"><section class="card"><div class="card-heading"><h2>从主要模块开始</h2>${tag('人工职责摘要')}</div><div class="module-list">${[['database','database.py','数据库入口与表访问','DB'],['table','table.py','文档增删改查与 ID 管理','Tb'],['queries','queries.py','查询条件的组合与求值','Q'],['storages','storages.py','数据的存储接口与实现','St']].map(([id,file,desc,icon])=>`<button class="module" data-module="${id}"><span class="module-icon">${icon}</span><span><strong>${file}</strong><small>${desc}</small></span><span>↗</span></button>`).join('')}</div><div class="callout">正式版选择单个提交即可浏览结构；职责解释会区分代码依据与模型推测。</div></section>
<aside><section class="card"><h2>一次分析，三个问题</h2><ol class="steps"><li>实际改了什么？<small>固定前后版本，定位文件与函数。</small></li><li>哪些地方需要检查？<small>沿依赖路径查看潜在影响与依据。</small></li><li>审核后有什么结论？<small>保留审核意见和手动测试记录。</small></li></ol></section><section class="card"><span class="eyebrow">RECENT ANALYSIS</span><h3>${escapeHtml(current.title)}</h3><p class="subtext">${current.base.slice(0,8)} → ${current.head.slice(0,8)}</p><div class="meta-row">${tag(status(current),'good')}${tag(reviewStatus(current))}</div>${button('继续查看 →','report','secondary small')}</section></aside></div>`;}
function newPage(){if(role!=='developer')return heading('NEW ANALYSIS','新建分析','审核者可查看报告并填写审核记录。')+`<div class="card empty"><h2>发起分析由开发者负责</h2><p>可以从历史记录打开报告，检查依据并留下审核意见。</p>${button('查看历史记录','history')}</div>`;
return heading('NEW ANALYSIS','定义这次要检查的修改','选定两个版本，留下目的；分析结果将与版本固定关联。')+`<div class="form-layout"><form id="analysis-form" class="card"><span class="field-title">分析类型</span><div class="radios"><label class="radio-card"><input type="radio" name="type" value="history" ${draft.type==='history'?'checked':''}> 历史提交分析<small>回看仓库已有的真实修改</small></label><label class="radio-card"><input type="radio" name="type" value="ai" ${draft.type==='ai'?'checked':''}> AI 修改记录<small>关联实际任务与前后版本</small></label></div>
<label class="form-field"><span id="purpose-label">${draft.type==='ai'?'实际提出的 AI 修改要求':'分析目的'} *</span><textarea name="purpose" required maxlength="3000">${escapeHtml(draft.purpose)}</textarea><small>原型可体验 AI 表单；当前提交仍是上游历史案例，不会被标记为真实 AI 产出。</small></label>
<label class="form-field"><span>基准提交 *</span><input name="base" type="text" value="${escapeHtml(draft.base)}" required spellcheck="false"><small>修改前。原型固定使用案例 B 的完整 SHA。</small></label><label class="form-field"><span>目标提交 *</span><input name="head" type="text" value="${escapeHtml(draft.head)}" required spellcheck="false"><small>修改后。填入相同 SHA 可体验无变更报告。</small></label>
<details ${draft.type==='ai'?'open':''}><summary>附加原始操作记录（可选）</summary><div style="margin-top:16px"><label class="form-field"><span>记录来源</span><input name="origin" type="text" placeholder="例如：工具名称、手工摘录" value="${escapeHtml(draft.origin)}" maxlength="200"></label><label class="form-field"><span>记录文本</span><textarea name="original" placeholder="只填写实际留存的记录；未提供的阶段将标注缺失。" maxlength="12000">${escapeHtml(draft.original)}</textarea></label></div></details>
<label class="check"><input type="checkbox" name="model" ${draft.model?'checked':''}><span>包含解释区示意<small class="muted" style="display:block">正式版在模型配置可用后生成；原型只展示人工示意文案。</small></span></label><p id="analysis-error" class="form-error" role="alert"></p><div class="form-actions"><button class="button" type="submit">生成示例报告 →</button>${button('返回概览','overview','secondary')}<small class="muted">不会触发分析或模型请求</small></div></form>
<aside><section class="card"><h2>这次使用的案例</h2><p class="subtext">TinyDB · 跳过不存在的文档 ID</p><table class="help-table"><tr><td>改动位置</td><td>Table.update / remove / upsert</td></tr><tr><td>核对重点</td><td>缺失 ID 与有效 ID 混合时的行为；upsert 对 update 的使用</td></tr><tr><td>证据边界</td><td>同类方法调用候选；动态转发关系仍需人工检查</td></tr></table><div class="callout">提交后固定版本与记录。正式版重试会新建关联任务，已有报告和审核保持可追溯。</div></section></aside></div>`;}
function impact(){return `<div class="graph-summary"><strong>${current.scenario==='empty'?'无变更 · 保留项目结构':'本次变更集中在 table.py'}</strong><span>${current.scenario==='empty'?'当前没有影响候选。':'update、remove、upsert 有改动；按模块依赖向调用方追踪潜在影响。'}</span></div>${window.codeGraph.render({empty:current.scenario==='empty',partial:current.scenario==='partial'})}
<div class="graph-followup"><section class="card"><h2>读图后，再核对行为</h2><p>${current.scenario==='empty'?'同版本比较没有变更，不生成风险猜测。':current.scenario==='model-failed'?'模型解释未生成，仍可在上图查看静态关系与影响候选。':'图中颜色表达待核对的影响，不代表已经发生故障。upsert 调用 update，因此两处改动需要结合检查。模块导入带来的候选比函数调用更粗，需要继续展开。'}</p><span class="tag">${current.model&&current.scenario!=='model-failed'?'人工阅读提示 · 非模型输出':'基础静态视图'}</span></section><section class="card"><h2>测试与审核</h2><p>已有测试线索：test_update_ids_missing、test_remove_ids_mixed。当前为人工关联，尚未执行。</p><button class="button secondary small" data-tab="review">去审核记录 →</button></section></div>`;}
function taskRecord(){return `<section class="card"><h2>任务与实际改动</h2><div class="meta-row">${tag(current.type==='ai'?'AI 表单示意 · 非真实 AI 案例':'历史提交分析')}</div><h3>${current.type==='ai'?'填写的任务要求':'分析目的'}</h3><p class="preserve">${escapeHtml(current.purpose)}</p><hr style="border:0;border-top:1px solid var(--line);margin:24px 0"><h3>原始操作记录</h3>${current.original?`<p class="subtext">来源：${escapeHtml(current.origin)}</p><p class="preserve">${escapeHtml(current.original)}</p>`:`<p class="muted">未提供。无法根据 diff 还原原始操作过程。</p>`}<div class="callout">报告中的解释属于事后分析，与原始任务、真实操作记录分别保存。当前版本来自上游历史案例；AI 表单内容仅供预览。</div></section>`;}
function reviews(){const records=current.reviews.slice().reverse().map(r=>`<article class="record"><div class="meta-row">${tag(r.decision,'good')}${tag('测试：'+r.test)}</div><strong>审核者 · 预览账号</strong><small> · ${escapeHtml(r.time)}</small><p>${escapeHtml(r.note)}</p><p class="muted">测试记录：${escapeHtml(r.detail || '未执行；原因见审核意见。')}</p></article>`).join('');
return `<div class="review-grid"><section class="card"><h2>对照这份报告留下结论</h2>${role==='reviewer'?`<form id="review-form"><label class="form-field"><span>审核结论 *</span><select name="decision"><option>需补充</option><option>已审核</option></select></label><label class="form-field"><span>审核意见 *</span><textarea name="note" required maxlength="4000" placeholder="写明核对了哪些依据、仍有什么问题；未测试时说明原因。"></textarea></label><label class="form-field"><span>手动测试状态</span><select name="test"><option>未执行</option><option>通过</option><option>未通过</option><option>受阻</option></select></label><label class="form-field"><span>执行步骤与结果</span><textarea name="detail" maxlength="4000" placeholder="通过/未通过：检查对象、实际命令或步骤与结果；受阻：原因。"></textarea></label><p class="section-note">平台未运行测试。这里记录审核者实际检查的结果；原型记录刷新后清空。</p><p id="review-error" class="form-error" role="alert"></p><div class="form-actions"><button class="button" type="submit">保存示例审核记录</button></div></form>`:`<div class="empty"><h3>开发者可以查看审核结果</h3><p>切换顶部的“预览角色”为审核者，即可体验填写意见和测试记录。</p></div>`}</section><section class="card"><h2>审核记录</h2><p class="subtext">每条记录关联报告 #${current.id}，修订时追加保留。</p>${records || '<div class="empty" style="margin-top:18px"><h3>等待首次审核</h3><p>尚未提交结论，也尚未记录测试结果。</p></div>'}</section></div>`;}
function report(){let notice='';if(current.scenario==='model-failed')notice='情形预览：模型解释请求失败。基础结果保留，任务标为部分完成。';if(current.scenario==='partial')notice='情形预览：部分文件解析失败，影响范围可能遗漏。正式版会列出文件、阶段及错误详情。';
return heading('CHANGE REPORT',current.title,'从整体代码关系定位改动，再逐层核对影响。',role==='developer'?button('新建分析','new','secondary'):'')+`<div class="version-strip"><div><small>基准版本 / 修改前</small><code>${current.base}</code></div><span class="muted">→</span><div><small>目标版本 / 修改后</small><code>${current.scenario==='empty'?current.base:current.head}</code></div></div><div class="status-strip"><div>${tag('示例报告 #'+current.id)} ${tag(status(current),status(current)==='完成'?'good':'warn')} ${tag(reviewStatus(current))}</div><span class="muted">${current.type==='ai'?'AI 表单示意 · 历史提交仅作占位':'历史提交分析'} · ${current.model?'解释区为人工示意':'未请求模型解释'}</span></div>${notice?`<div class="notice" role="status">${notice}</div>`:''}<div class="tabs" role="tablist" aria-label="报告内容">${[['impact','改动与影响'],['task','任务记录'],['review','审核记录']].map(([id,name])=>`<button role="tab" aria-selected="${tab===id}" class="${tab===id?'active':''}" data-tab="${id}">${name}${id==='review'&&current.reviews.length?' · '+current.reviews.length:''}</button>`).join('')}</div><div role="tabpanel">${tab==='impact'?impact():tab==='task'?taskRecord():reviews()}</div>`;}
function history(){return heading('ANALYSIS HISTORY','每次修改，都有据可回看','报告与审核关联固定版本；再次打开不会重新调用模型。',role==='developer'?button('＋ 新建分析','new'):'')+`<div class="history-list">${reports.slice().reverse().map(r=>`<article class="history-item"><div><span class="eyebrow">REPORT #${r.id} / 示例</span><h3>${escapeHtml(r.title)}</h3><p><code>${r.base.slice(0,8)} → ${(r.scenario==='empty'?r.base:r.head).slice(0,8)}</code> · ${r.type==='history'?'历史提交分析':'AI 表单示意'}</p><div class="tags">${tag(status(r),'good')}${tag(reviewStatus(r))}${tag('仅本次预览')}</div></div><button class="button secondary small" data-report="${r.id}">查看 →</button></article>`).join('')}</div>`;}
function render(){$('main').classList.toggle('report-wide',page==='report');document.querySelectorAll('[data-nav]').forEach(a=>{a.classList.toggle('active',a.dataset.nav===page);if(a.dataset.nav==='new')a.setAttribute('aria-disabled',String(role!=='developer'));});$('role-name').textContent=role==='developer'?'开发者':'审核者';$('avatar').textContent=role==='developer'?'D':'R';$('scenario').value=current.scenario;$('main').innerHTML=({overview,new:newPage,report,history}[page])()+footer;}
function navigate(target){if(!['overview','new','report','history'].includes(target))target='overview';page=target;if(location.hash!==`#${target}`)location.hash=target;else render();}
function openEvidence(target=entity){$('dialog-content').innerHTML=`<div class="eyebrow">EVIDENCE PREVIEW</div><h2 id="dialog-title">${target==='remove'?'D-02 · Table.remove 变更':'E-01 · upsert 调用 update'}</h2><p>${target==='remove'?'样例验证已核对 Table.remove 在这次历史修复中发生改动。':'样例验证已核对同类方法调用 self.update(...)。这里保留的是候选关系，正式解析仍需考虑作用域、遮蔽及继承。'}</p><table class="help-table"><tr><td>所属版本</td><td><code>${HEAD}</code></td></tr><tr><td>文件</td><td><code>tinydb/table.py</code></td></tr><tr><td>依据层次</td><td>真实历史案例中的人工核对；不是本次自动分析结果</td></tr></table><div class="callout">此原型展示证据面板的内容安排。正式版会打开对应提交的真实源码并定位行号，当前未接入源码定位。</div>`;$('evidence-dialog').showModal();}
document.addEventListener('click',e=>{const action=e.target.closest('[data-action]');if(action){const a=action.dataset.action;if(a==='evidence')openEvidence();else navigate(a);}const t=e.target.closest('[data-tab]');if(t){tab=t.dataset.tab;render();}const n=e.target.closest('[data-entity]');if(n){entity=n.dataset.entity;render();}const ev=e.target.closest('[data-evidence]');if(ev)openEvidence(ev.dataset.evidence);const r=e.target.closest('[data-report]');if(r){current=reports.find(x=>x.id===Number(r.dataset.report));tab='impact';navigate('report');}const m=e.target.closest('[data-module]');if(m){$('dialog-content').innerHTML=`<div class="eyebrow">MODULE PREVIEW</div><h2 id="dialog-title">tinydb/${escapeHtml(m.dataset.module)}.py</h2><p>这里将展示单版本模块的实体、关系及对应源码。原型先让你确认从模块进入详情的阅读方式。</p><div class="callout">职责来自人工摘要。正式版模型说明需引用代码依据；结构关系与推测内容分别标识。</div><p class="subtext">预览版本：<code>${HEAD}</code></p>`;$('evidence-dialog').showModal();}});
document.addEventListener('input',e=>{if(e.target.closest('#analysis-form')){const f=e.target;draft[f.name]=f.type==='checkbox'?f.checked:f.value;if(f.name==='type'){$('purpose-label').textContent=f.value==='ai'?'实际提出的 AI 修改要求 *':'分析目的 *';document.querySelector('#analysis-form details').open=f.value==='ai';}}});
document.addEventListener('submit',e=>{if(e.target.id==='analysis-form'){e.preventDefault();const form=e.target;if(role!=='developer')return;const data=new FormData(form),base=data.get('base').trim(),head=data.get('head').trim(),purpose=data.get('purpose').trim(),original=data.get('original').trim(),origin=data.get('origin').trim();if(!purpose){$('analysis-error').textContent='请填写分析目的或真实任务要求。';return;}if(![BASE,HEAD].includes(base)||![BASE,HEAD].includes(head)||(base===HEAD&&head===BASE)){$('analysis-error').textContent='此原型只预览固定案例 B：请使用预填版本，或将两个版本设为相同以查看无变更。正式版将解析实际 Git 引用。';return;}if(original&&!origin){$('analysis-error').textContent='附加操作记录时，请注明记录来源。';return;}current={id:nextId++,title:purpose.length>32?purpose.slice(0,32)+'…':purpose,type:data.get('type'),purpose,base,head,original,origin,model:data.has('model'),scenario:base===head?'empty':'normal',reviews:[]};reports.push(current);tab='impact';entity='update';navigate('report');toast('已生成交互示例，未运行真实分析。');}
if(e.target.id==='review-form'){e.preventDefault();if(role!=='reviewer')return;const f=new FormData(e.target),note=f.get('note').trim(),detail=f.get('detail').trim(),test=f.get('test');if(!note){$('review-error').textContent='请填写审核意见。';return;}if(test!=='未执行'&&!detail){$('review-error').textContent='请补充实际执行步骤与结果，或受阻原因。';return;}current.reviews.push({decision:f.get('decision'),note,test,detail,time:new Date().toLocaleString('zh-CN',{hour12:false})});render();toast('审核示例已保存；刷新页面会重置。');}});
$('role').addEventListener('change',e=>{role=e.target.value;render();});
$('scenario').addEventListener('change',e=>{current.scenario=e.target.value;if(current.scenario==='model-failed')current.model=true;tab='impact';navigate('report');toast('已切换报告情形，仅为状态预览。');});
window.addEventListener('hashchange',()=>{page=location.hash.slice(1);if(!['overview','new','report','history'].includes(page))page='overview';render();window.scrollTo(0,0);});
page=location.hash.slice(1)||'overview';if(!['overview','new','report','history'].includes(page))page='overview';render();
